   805  static enum lwan_http_status
   806  read_from_request_socket(struct lwan_request *request,
   807                           struct lwan_value *buffer,
   808                           const size_t buffer_size,
   809                           enum lwan_read_finalizer (*finalizer)(
   810                               size_t total_read,
   811                               size_t buffer_size,
   812                               struct lwan_request *request,
   813                               int n_packets))
   814  {
   815      struct lwan_request_parser_helper *helper = request->helper;
   816      ssize_t n;
   817      size_t total_read = 0;
   818      int n_packets = 0;
   819
   820      if (helper->next_request) {
   821          const size_t next_request_len = (size_t)(helper->next_request - buffer->value);
   822          size_t new_len;
   823
   824          if (__builtin_sub_overflow(buffer->len, next_request_len, &new_len)) {
   825              helper->next_request = NULL;
   826          } else {
   827              /* FIXME: This memmove() could be eventually removed if a better
   828               * stucture (maybe a ringbuffer, reading with readv(), and each
   829               * pointer is coro_strdup() if they wrap around?) were used for
   830               * the request buffer.  */
   831              total_read = buffer->len = new_len;
   832              memmove(buffer->value, helper->next_request, new_len);
   833              goto try_to_finalize;
   834          }
   835      }
   836
   837      for (;; n_packets++) {
   838          size_t to_read = (size_t)(buffer_size - total_read);
   839
   840          if (UNLIKELY(to_read == 0))
   841              return HTTP_TOO_LARGE;
   842
   843          n = read(request->fd, buffer->value + total_read, to_read);
   844          if (UNLIKELY(n <= 0)) {
   845              if (n < 0) {
   846                  switch (errno) {
   847                  case EAGAIN:
   848                      coro_yield(request->conn->coro, CONN_CORO_WANT_READ);
   849                      continue;
   850                  case EINTR:
   851  yield_and_read_again:
   852                      coro_yield(request->conn->coro, CONN_CORO_YIELD);
   853                      continue;
   854                  }
   855
   856                  /* Unexpected error before reading anything */
   857                  if (UNLIKELY(!total_read))
   858                      return HTTP_BAD_REQUEST;
   859              }
   860
   861              /* Client shut down orderly (n = 0), or unrecoverable error (n < 0);
   862               * shut down coro. */
   863              break;
   864          }
   865
   866          total_read += (size_t)n;
   867          buffer->len = (size_t)total_read;
   868
   869  try_to_finalize:
   870          switch (finalizer(total_read, buffer_size, request, n_packets)) {
   871          case FINALIZER_DONE:
   872              buffer->value[buffer->len] = '\0';
   873
   874  #if defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
   875              save_to_corpus_for_fuzzing(buffer);
   876  #endif
   877
   878              return HTTP_OK;
   879
   880          case FINALIZER_TRY_AGAIN:
   881              goto yield_and_read_again;
   882
   883          case FINALIZER_ERROR_TIMEOUT:
   884              return HTTP_TIMEOUT;
   885          }
   886      }
   887
   888      coro_yield(request->conn->coro, CONN_CORO_ABORT);
   889      __builtin_unreachable();
   890      return HTTP_INTERNAL_ERROR;
   891  }
