   893  static enum lwan_read_finalizer
   894  read_request_finalizer(size_t total_read,
   895                         size_t buffer_size __attribute__((unused)),
   896                         struct lwan_request *request,
   897                         int n_packets)
   898  {
   899      static const size_t min_proxied_request_size =
   900          MIN_REQUEST_SIZE + sizeof(struct proxy_header_v2);
   901      struct lwan_request_parser_helper *helper = request->helper;
   902
   903      /* Yield a timeout error to avoid clients being intentionally slow and
   904       * hogging the server.  (Clients can't only connect and do nothing, they
   905       * need to send data, otherwise the DQ timer will kick in and close the
   906       * connection.  Limit the number of packets to avoid them sending just
   907       * a byte at a time.)
   908       * See calculate_n_packets() to see how this is calculated. */
   909      if (UNLIKELY(n_packets > helper->error_when_n_packets))
   910          return FINALIZER_ERROR_TIMEOUT;
   911
   912      char *crlfcrlf =
   913          memmem(helper->buffer->value, helper->buffer->len, "\r\n\r\n", 4);
   914      if (LIKELY(crlfcrlf)) {
   915          const size_t crlfcrlf_to_base =
   916              (size_t)(crlfcrlf - helper->buffer->value);
   917
   918          if (LIKELY(helper->next_request)) {
   919              helper->next_request = NULL;
   920              return FINALIZER_DONE;
   921          }
   922
   923          if (crlfcrlf_to_base >= MIN_REQUEST_SIZE - 4)
   924              return FINALIZER_DONE;
   925
   926          if (total_read > min_proxied_request_size &&
   927              request->flags & REQUEST_ALLOW_PROXY_REQS) {
   928              /* FIXME: Checking for PROXYv2 protocol header here is a layering
   929               * violation. */
   930              STRING_SWITCH_LARGE (crlfcrlf + 4) {
   931              case STR8_INT(0x00, 0x0d, 0x0a, 0x51, 0x55, 0x49, 0x54, 0x0a):
   932                  return FINALIZER_DONE;
   933              }
   934          }
   935      }
   936
   937      return FINALIZER_TRY_AGAIN;
   938  }
