   940  static ALWAYS_INLINE enum lwan_http_status
   941  read_request(struct lwan_request *request)
   942  {
   943      return read_from_request_socket(request, request->helper->buffer,
   944                                      DEFAULT_BUFFER_SIZE - 1 /* -1 for NUL byte */,
   945                                      read_request_finalizer);
   946  }
