   948  static enum lwan_read_finalizer
   949  post_data_finalizer(size_t total_read,
   950                      size_t buffer_size,
   951                      struct lwan_request *request,
   952                      int n_packets)
   953  {
   954      struct lwan_request_parser_helper *helper = request->helper;
   955
   956      if (buffer_size == total_read)
   957          return FINALIZER_DONE;
   958
   959      /* For POST requests, the body can be larger, and due to small MTUs on
   960       * most ethernet connections, responding with a timeout solely based on
   961       * number of packets doesn't work.  Use keepalive timeout instead.  */
   962      if (UNLIKELY(time(NULL) > helper->error_when_time))
   963          return FINALIZER_ERROR_TIMEOUT;
   964
   965      /* In addition to time, also estimate the number of packets based on an
   966       * usual MTU value and the request body size.  */
   967      if (UNLIKELY(n_packets > helper->error_when_n_packets))
   968          return FINALIZER_ERROR_TIMEOUT;
   969
   970      return FINALIZER_TRY_AGAIN;
   971  }
