  1000
  1001      if (!(st.st_mode & S_ISVTX)) {
  1002          lwan_status_warning(
  1003              "Using %s as temporary directory, but it doesn't have "
  1004              "the sticky bit set.",
  1005              v);
  1006      }
  1007
  1008      return v;
