  1482  const char *lwan_request_get_header(struct lwan_request *request,
  1483                                      const char *header)
  1484  {
  1485      char name[64];
  1486      int r;
  1487
  1488      r = snprintf(name, sizeof(name), "%s: ", header);
  1489      if (UNLIKELY(r < 0 || r >= (int)sizeof(name)))
  1490          return NULL;
  1491
  1492      for (size_t i = 0; i < request->helper->n_header_start; i++) {
  1493          const char *start = request->helper->header_start[i];
  1494          char *end = request->helper->header_start[i + 1] - HEADER_TERMINATOR_LEN;
  1495
  1496          if (UNLIKELY(end - start < r))
  1497              continue;
  1498
  1499          if (!strncasecmp(start, name, (size_t)r)) {
  1500              *end = '\0';
  1501              return start + r;
  1502          }
  1503      }
  1504
  1505      return NULL;
  1506  }
